let allAlbums=[],currentCategory="all",searchQuery="";function setupNavigation(){const e=document.getElementById("mobileMenuBtn"),t=document.getElementById("navMenu");e&&t&&(e.addEventListener("click",()=>{t.classList.toggle("open")}),document.querySelectorAll(".nav-item").forEach(e=>{e.addEventListener("click",()=>{t.classList.remove("open")})})),window.addEventListener("scroll",()=>{const e=document.getElementById("header");e&&(window.scrollY>50?e.style.boxShadow="0 6px 25px rgba(0, 0, 0, 0.08)":e.style.boxShadow="0 4px 20px rgba(0, 0, 0, 0.03)")})}function setupAdminIndicator(){const e=window.YellowRoseDB.isAdminAuthenticated(),t=document.getElementById("adminSecretBadge");t&&(t.style.display=e?"inline-flex":"none")}async function loadAndRenderAlbums(){const e=document.getElementById("galleryGrid");if(e){e.innerHTML='\n    <div class="loading-state" style="grid-column: 1 / -1; text-align: center; padding: 50px 20px;">\n      <i class="fas fa-spinner fa-spin" style="font-size: 32px; color: var(--gold-primary);"></i>\n      <p style="margin-top: 15px; color: var(--text-muted); font-size: 16px;">جاري تحميل أعمال وألبومات يلوروز الفاخرة...</p>\n    </div>\n  ';try{allAlbums=await window.YellowRoseDB.getAlbums(),updateCategoryCounts(),renderGallery()}catch(t){e.innerHTML='\n      <div style="grid-column: 1 / -1; text-align: center; padding: 40px;">\n        <p style="color: #c0392b;">حدث خطأ أثناء تحميل الألبومات، يرجى إعادة المحاولة.</p>\n      </div>\n    '}}}function renderGallery(){const e=document.getElementById("galleryGrid"),t=document.getElementById("noItemsMessage");if(!e)return;e.innerHTML="";const n=Object.values(window.CATEGORIES);let a=0;n.forEach(t=>{if("all"!==currentCategory&&t.id!==currentCategory)return;if(searchQuery&&!t.name.toLowerCase().includes(searchQuery.toLowerCase()))return;const n=allAlbums.filter(e=>e.category===t.id);let l=0,r="assets/logo.png",s=!1;if(!(n.length>0))return;n.forEach(e=>{e.images&&e.images.length>0&&(l+=e.images.length),e.featured&&(s=!0)});for(let e=n.length-1;e>=0;e--){const t=n[e];if(t.coverUrl){r=t.coverUrl;break}if(t.images&&t.images.length>0){r=t.images[0].thumbnailUrl||t.images[0].url;break}}a++;const c=document.createElement("div");c.className="album-card category-card",c.setAttribute("data-id",t.id),c.innerHTML=`\n      <div class="card-img-wrapper">\n        <a href="album.html?category=${t.id}" class="card-img-link" title="استعراض قسم ${escapeHtml(t.name)}">\n          <img src="${escapeHtml(r)}" alt="${escapeHtml(t.name)}" class="card-img" loading="lazy" onerror="this.src='assets/logo.png';">\n        </a>\n        <span class="card-category-badge" style="top: 15px; left: auto; right: 15px; background: rgba(0,0,0,0.6); backdrop-filter: blur(5px);">\n          <i class="fas ${t.icon||"fa-tag"}"></i> ${escapeHtml(t.name)}\n        </span>\n        <span class="card-photo-count">\n          <i class="fas fa-camera"></i> ${l} ${l>10?"صورة":"صور"}\n        </span>\n        ${s?'<span class="card-featured-badge"><i class="fas fa-star"></i> قسم مميز</span>':""}\n      </div>\n\n      <div class="card-body">\n        <h3 class="card-title" style="margin-bottom: 5px;">\n          <a href="album.html?category=${t.id}">${escapeHtml(t.name)}</a>\n        </h3>\n        <p class="card-desc">استعرض جميع صور وتنسيقات قسم ${escapeHtml(t.name)} بشكل مباشر.</p>\n        \n        <div class="card-album-actions" style="margin-top: 15px;">\n          <a href="album.html?category=${t.id}" class="btn-card-album" style="width: 100%; justify-content: center;">\n            <i class="fas fa-images"></i> عرض جميع الصور\n          </a>\n        </div>\n      </div>\n    `,e.appendChild(c)}),0===a?t&&t.classList.remove("hidden"):t&&t.classList.add("hidden")}function updateCategoryCounts(){const e=document.getElementById("count-all");e&&(e.textContent=allAlbums.length),Object.keys(window.CATEGORIES).forEach(e=>{const t=document.getElementById(`count-${e}`);if(t){const n=allAlbums.filter(t=>t.category===e).length;t.textContent=n}})}function setupFilterAndSearch(){document.querySelectorAll(".cat-btn").forEach(e=>{e.addEventListener("click",()=>{document.querySelectorAll(".cat-btn").forEach(e=>e.classList.remove("active")),e.classList.add("active"),currentCategory=e.getAttribute("data-category"),renderGallery()})});const e=document.getElementById("gallerySearchInput");e&&e.addEventListener("input",e=>{searchQuery=e.target.value.trim(),renderGallery()})}function escapeHtml(e){return e?String(e).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;"):""}document.addEventListener("DOMContentLoaded",async()=>{await window.YellowRoseDB.syncSiteSettingsToDom(),setupNavigation(),setupAdminIndicator(),await loadAndRenderAlbums(),setupFilterAndSearch()});